1449→// prepareTranscriptIfNeeded calls PrepareTranscript for agents that implement
1450→// the TranscriptPreparer interface. This ensures transcript files exist before
1451→// they are read (e.g., OpenCode creates its transcript lazily via `opencode export`).
1452→// Errors are silently ignored — this is best-effort for hook paths.
1453→func prepareTranscriptIfNeeded(agentType agent.AgentType, transcriptPath string) {
1454→	if transcriptPath == "" {
1455→		return
1456→	}
1457→	ag, err := agent.GetByAgentType(agentType)
1458→	if err != nil {
1459→		return
1460→	}
1461→	if preparer, ok := ag.(agent.TranscriptPreparer); ok {
